using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace MaohaiziPet {
public static class CatHabitsTests {
    static LivingReport report;
    static void Assert(bool value,string error){if(!value)throw new Exception(error);}
    static void Check(string name,Action test){var r=new TestResult{name=name};try{test();r.passed=true;report.passed++;}catch(Exception e){r.error=e.Message;report.failed++;}report.tests.Add(r);}
    static byte[] Pixels(BitmapSource image){byte[] p=new byte[256*256*4];image.CopyPixels(p,1024,0);return p;}
    static BitmapSource Copy(BitmapSource image){return BitmapSource.Create(256,256,96,96,PixelFormats.Pbgra32,null,Pixels(image),1024);}
    static void Save(BitmapSource image,string path){var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var f=File.Create(path))png.Save(f);}
    public static int Run(string manifest,string output){
        Directory.CreateDirectory(output);report=new LivingReport();report.scope="Natural cat behavior scheduling, yawn aperture, physical continuity, interruption and asset readiness";
        Check("未备好素材的主要动作和姿态不会开放",delegate{var h=new CatHabits(9);foreach(var action in new[]{CatHabit.Yawn,CatHabit.Groom,CatHabit.BellyRoll,CatHabit.SitUp,CatHabit.StandUp,CatHabit.CurlSleep})Assert(!h.Start(action,PetMode.Companion,false),"未准备的动作被开放："+action);});
        Check("哈欠草稿有起手与收尾，不在第一帧突然张嘴",delegate{var h=new CatHabits(9){YawnReady=true};var s=new CompanionSignals();h.Start(CatHabit.Yawn,PetMode.Companion,false);h.Apply(s);Assert(s.Yawn==0,"起手硬切");h.Tick(2.2,PetMode.Companion,false,false);h.Apply(s);Assert(s.Yawn>.95,"没有张口峰值");h.Tick(3,PetMode.Companion,false,false);h.Apply(s);Assert(!h.Active&&s.Yawn==0,"哈欠未结束");});
        Check("专注和勿扰不会产生自主表演",delegate{foreach(bool focus in new[]{false,true}){var h=new CatHabits(9){SitReady=true,StandReady=true,SleepReady=true,GroomReady=true,YawnReady=true};for(int i=0;i<600;i++)h.Tick(1,focus?PetMode.Companion:PetMode.Quiet,focus,false);Assert(h.AutomaticCount==0&&!h.Active,"安静模式被打扰");}});
        Check("手动互动能中断动作，稍作停顿再自主活动",delegate{var h=new CatHabits(9);h.Start(CatHabit.FrontStretch,PetMode.Companion,false);h.Tick(1,PetMode.Companion,false,true);Assert(!h.Active,"互动没有抢占主要动作");h.Tick(3,PetMode.Companion,false,false);Assert(!h.Active,"中断后马上反复表演");for(int i=0;i<10;i++)h.Tick(1,PetMode.Companion,false,false);Assert(h.AutomaticCount>0,"互动后永久停止了自主活动");});
        Check("无人点击会及时自主活动，有变化和停顿",delegate{var h=new CatHabits(9);var seen=new HashSet<CatHabit>();double first=0,previous=0;var intervals=new HashSet<int>();int revision=0;for(int i=0;i<1800;i++){h.Tick(1,PetMode.Companion,false,false);Assert(h.Current!=CatHabit.Groom&&h.Current!=CatHabit.BellyRoll,"自动播放了未准备姿态");if(h.Revision!=revision){revision=h.Revision;seen.Add(h.Current);if(first==0)first=h.Clock;if(previous>0)intervals.Add((int)(h.Clock-previous));previous=h.Clock;}}Assert(first>=7&&first<=12,"首次活动过晚");Assert(h.AutomaticCount>=50&&h.AutomaticCount<=160,"自主行为过于频繁或长期停滞");Assert(seen.Count>=3&&intervals.Count>=4,"机械重复同一动作和间隔");});
        Check("已有素材的舔毛和哈欠会自行发生，无需按钮",delegate{var h=new CatHabits(41){GroomReady=true,YawnReady=true,BellyReady=true,Familiarity=20};h.SetMotionDuration(CatHabit.Groom,5);h.SetMotionDuration(CatHabit.Yawn,5);h.SetMotionDuration(CatHabit.BellyRoll,5);var seen=new HashSet<CatHabit>();for(int i=0;i<1800;i++){h.Tick(.25,PetMode.Companion,false,false);if(h.Active)seen.Add(h.Current);}Assert(seen.Contains(CatHabit.Groom)&&seen.Contains(CatHabit.Yawn)&&seen.Contains(CatHabit.PawPlay),"生成动作仍只在点击后播放");});
        Check("无人点击时先展示三种新姿态，坐睡都有持续停留",delegate{var h=new CatHabits(71){SitReady=true,StandReady=true,SleepReady=true,GroomReady=true,YawnReady=true};var seen=new HashSet<CatHabit>();double sit=0,sleep=0;CatHabit first=CatHabit.None;for(int i=0;i<1200;i++){h.Tick(.1,PetMode.Companion,false,false);if(h.Active){if(first==CatHabit.None)first=h.Current;seen.Add(h.Current);if(h.Current==CatHabit.SitUp)sit+=.1;if(h.Current==CatHabit.CurlSleep)sleep+=.1;}}Assert(first==CatHabit.SitUp,"启动后仍只在原地趴着");Assert(seen.Contains(CatHabit.SitUp)&&seen.Contains(CatHabit.StandUp)&&seen.Contains(CatHabit.CurlSleep),"新姿态被旧动作长期饿死");Assert(sit>=14&&sleep>=22,"坐姿或睡姿一闪而过");});
        Check("睡醒后可以活动，但不会重播刚做过的伸展",delegate{var h=new CatHabits(19){SitReady=true,StandReady=true,SleepReady=true};h.Start(CatHabit.SitUp,PetMode.Companion,false);h.Start(CatHabit.StandUp,PetMode.Companion,false);h.Start(CatHabit.CurlSleep,PetMode.Companion,false);h.Tick(h.Duration+.1,PetMode.Companion,false,false);h.Tick(11,PetMode.Companion,false,false);Assert(h.Current!=CatHabit.StandUp,"睡醒后重复了刚做过的站立伸展");});
        Check("长时间无人操作也遵守动作冷却，不连续表演同一动作",delegate{for(int seed=0;seed<24;seed++){var h=new CatHabits(seed){SitReady=true,StandReady=true,SleepReady=true,GroomReady=true,YawnReady=true};var last=new Dictionary<CatHabit,double>();CatHabit previous=CatHabit.None;int revision=0;for(int i=0;i<14400;i++){h.Tick(.25,PetMode.Companion,false,false);if(h.Revision==revision)continue;revision=h.Revision;Assert(h.Current!=previous,"相邻两次完整动作完全相同");if(last.ContainsKey(h.Current))Assert(h.Clock-last[h.Current]>=CatHabits.Cooldown(h.Current),"动作尚在冷却就重复："+h.Current);last[h.Current]=h.Clock;previous=h.Current;}Assert(h.AutomaticCount>40,"避免重复导致长期不活动");}});
        Check("轻动作不会长期饿死坐站姿态",delegate{for(int seed=0;seed<20;seed++){var h=new CatHabits(seed){SitReady=true,StandReady=true,GroomReady=true,YawnReady=true};h.SetMotionDuration(CatHabit.SitUp,10);h.SetMotionDuration(CatHabit.StandUp,10);double last=0;int revision=0,count=0;for(int i=0;i<7200;i++){h.Tick(.25,PetMode.Companion,false,false);if(h.Revision!=revision){revision=h.Revision;if(h.Current==CatHabit.SitUp||h.Current==CatHabit.StandUp){Assert(h.Clock-last<58,"超过58秒没有改变主要姿态");last=h.Clock;count++;}}}Assert(count>30,"姿态变化次数不足");}});
        Check("一次自主玩耍只有一段试探拍爪",delegate{var h=new CatHabits(31);h.Start(CatHabit.PawPlay,PetMode.Companion,false);var s=new CompanionSignals();int bursts=0;bool raised=false;for(int i=0;i<400;i++){h.Tick(.02,PetMode.Companion,false,false);h.Apply(s);bool now=s.PawLeft+s.PawRight>.1;if(now&&!raised)bursts++;raised=now;}Assert(bursts==1,"单个动作内反复挥爪");});
        Check("玩耍先观察再试探，最后收爪",delegate{var m=new CompanionMind(0,Personality.Clingy);m.Trigger(CompanionGesture.Play,PetMode.Companion);m.Tick(.5,PetMode.Companion,0);Assert(m.Signals.Play>.1&&m.Signals.PawLeft+m.Signals.PawRight==0,"没有观察阶段");m.Tick(1.6,PetMode.Companion,0);Assert(m.Signals.Hunt>.1&&m.Signals.PawLeft+m.Signals.PawRight>.1,"没有试探拍球");m.Tick(5.8,PetMode.Companion,0);Assert(m.Signals.PawLeft+m.Signals.PawRight==0,"结束还在挥爪");});
        var skin=PetSkin.Load(manifest);var frames=new List<BitmapSource>();
        Check("哈欠张口、眼睑与下巴实际连续变化且回到原面部",delegate{
            var h=new CatHabits(9){YawnReady=true};h.Start(CatHabit.Yawn,PetMode.Companion,false);var rig=new LivingPet(skin.Frames[0],113,skin.Living.ModernTexture);var s=new CompanionSignals();byte[] initial=Pixels(rig.Render());double largestStep=0,last=0;var sample=new[]{1,55,100,145,215,290,420};
            for(int i=0;i<=420;i++){h.Tick(1.0/60,PetMode.Companion,false,false);h.Apply(s);rig.Advance(1.0/60,PetAction.Idle,PetMode.Companion,new Point(0,0),s);largestStep=Math.Max(largestStep,Math.Abs(rig.Pose.Yawn-last));last=rig.Pose.Yawn;if(sample.Contains(i)){var copy=Copy(rig.Render());frames.Add(copy);Save(copy,Path.Combine(output,"yawn-"+i+".png"));}if(i==145){Assert(rig.Pose.Yawn>.9&&rig.Pose.BlinkLeft>.9,"嘴和眼睛没有协调");byte[] open=Pixels(rig.Render());long diff=0;for(int y=113;y<140;y++)for(int x=123;x<149;x++)diff+=Math.Abs(open[(y*256+x)*4+2]-initial[(y*256+x)*4+2]);Assert(diff>15000,"仅摇头而没有嘴部动画");}}
            Assert(largestStep<.035&&rig.Pose.Yawn<.01,"哈欠结束存在硬切或未合嘴");
        });
        Check("伸前爪时底部保持贴地，结束姿态平滑归位",delegate{var h=new CatHabits(9);var rig=new LivingPet(skin.Frames[0],113,skin.Living.ModernTexture);var s=new CompanionSignals();h.Start(CatHabit.FrontStretch,PetMode.Companion,false);double max=0;for(int i=0;i<420;i++){h.Tick(1.0/60,PetMode.Companion,false,false);h.Apply(s);rig.Advance(1.0/60,PetAction.Idle,PetMode.Companion,null,s);max=Math.Max(max,rig.Pose.Stretch);Assert((rig.MapToSource(new Point(130,240))-new Point(130,240)).Length<.001,"整只猫漂浮");}Assert(max>.8&&rig.Pose.Stretch<.01,"伸爪未完成或未恢复");});
        if(frames.Count>0){var v=new DrawingVisual();using(var d=v.RenderOpen()){d.DrawRectangle(new SolidColorBrush(Color.FromRgb(245,243,236)),null,new Rect(0,0,frames.Count*256,286));for(int i=0;i<frames.Count;i++){d.DrawImage(frames[i],new Rect(i*256,0,256,256));d.DrawText(new FormattedText(new[]{"起手","慢慢张嘴","张口","哈欠峰值","合嘴","放松","恢复待机"}[i],System.Globalization.CultureInfo.GetCultureInfo("zh-CN"),FlowDirection.LeftToRight,new Typeface("Microsoft YaHei"),13,Brushes.DimGray),new Point(i*256+90,264));}}var sheet=new RenderTargetBitmap(frames.Count*256,286,96,96,PixelFormats.Pbgra32);sheet.Render(v);Save(sheet,Path.Combine(output,"yawn-sequence-review.png"));}
        using(var f=File.Create(Path.Combine(output,"habits-test-report.json")))new DataContractJsonSerializer(typeof(LivingReport)).WriteObject(f,report);return report.failed==0?0:1;
    }
}
}
